  async getStageUpdates(stageId: string, includeInternal = false): Promise<(StageUpdate & { photos: StageUpdatePhoto[]; replies: StageUpdateReply[] })[]> {
    const conditions = [
      eq(stageUpdates.stageId, stageId),
      !includeInternal ? eq(stageUpdates.isInternal, false) : undefined,
    ].filter(Boolean) as any[];

    const whereClause = conditions.length ? and(...conditions) : undefined;

    const updates = await db
      .select()
      .from(stageUpdates)
      .where(whereClause)
      .orderBy(desc(stageUpdates.createdAt));

    // Get photos and replies for all updates
    const updateIds = updates.map(u => u.id);
    if (updateIds.length === 0) return [];

    const [photos, replies] = await Promise.all([
      db.select().from(stageUpdatePhotos).where(inArray(stageUpdatePhotos.updateId, updateIds)),
      db.select().from(stageUpdateReplies).where(inArray(stageUpdateReplies.updateId, updateIds))
    ]);

    // Group by update ID
    const photosByUpdate = photos.reduce((acc, photo) => {
      if (!acc[photo.updateId]) acc[photo.updateId] = [];
      acc[photo.updateId].push(photo);
      return acc;
    }, {} as Record<string, StageUpdatePhoto[]>);

    const repliesByUpdate = replies.reduce((acc, reply) => {
      if (!acc[reply.updateId]) acc[reply.updateId] = [];
      acc[reply.updateId].push(reply);
      return acc;
    }, {} as Record<string, StageUpdateReply[]>);

    return updates.map(update => ({
      ...update,
      photos: photosByUpdate[update.id] || [],
      replies: repliesByUpdate[update.id] || [],
    }));
  }

  async getStageUpdate(id: string): Promise<(StageUpdate & { photos: StageUpdatePhoto[]; replies: StageUpdateReply[] }) | undefined> {
    const [update] = await db
      .select()
      .from(stageUpdates)
      .where(eq(stageUpdates.id, id));

    if (!update) return undefined;

    const [photos, replies] = await Promise.all([
      db.select().from(stageUpdatePhotos).where(eq(stageUpdatePhotos.updateId, id)),
      db.select().from(stageUpdateReplies).where(eq(stageUpdateReplies.updateId, id))
    ]);

    return {
      ...update,
      photos,
      replies,
    };
  }

  async createStageUpdateReply(replyData: CreateStageUpdateReplyRequest): Promise<StageUpdateReply> {
    const [reply] = await db
      .insert(stageUpdateReplies)
      .values(replyData)
      .returning();

    return reply;
  }

  async getStageUpdateReplies(updateId: string): Promise<StageUpdateReply[]> {
    const replies = await db
      .select()
      .from(stageUpdateReplies)
      .where(eq(stageUpdateReplies.updateId, updateId))
      .orderBy(stageUpdateReplies.createdAt);

    return replies;
  }

  // Customer Questions operations
  async getAllCustomerQuestions(): Promise<any[]> {
    // Customer questions are stored as stageUpdateReplies with isCustomerQuestion: true
    // We need to join through: replies -> updates -> stages -> processes -> orders -> users
    const customerQuestions = await db
      .select({
        question: stageUpdateReplies,
        update: stageUpdates,
        stage: manufacturingStages,
        process: manufacturingProcesses,
        order: orders,
        user: users,
      })
      .from(stageUpdateReplies)
      .leftJoin(stageUpdates, eq(stageUpdateReplies.updateId, stageUpdates.id))
      .leftJoin(manufacturingStages, eq(stageUpdates.stageId, manufacturingStages.id))
      .leftJoin(manufacturingProcesses, eq(manufacturingStages.processId, manufacturingProcesses.id))
      .leftJoin(orders, eq(manufacturingProcesses.orderId, orders.id))
      .leftJoin(users, eq(orders.userId, users.id))
      .where(eq(stageUpdateReplies.isCustomerQuestion, true))
      .orderBy(desc(stageUpdateReplies.createdAt));

    // Fetch admin replies for each customer question
    const questionIds = customerQuestions.map(item => item.question.id);

    // Handle empty array case to prevent inArray error
    let repliesByQuestion: Record<string, StageUpdateReply[]> = {};
    if (questionIds.length > 0) {
      // Get replies to the same parent update that are NOT customer questions (admin replies)
      const allReplies = await db
        .select()
        .from(stageUpdateReplies)
        .where(
          and(
            inArray(stageUpdateReplies.updateId, customerQuestions.map(q => q.question.updateId)),
            eq(stageUpdateReplies.isCustomerQuestion, false)
          )
        )
        .orderBy(stageUpdateReplies.createdAt);

      // Group replies by the customer question they're responding to
      // Since all replies to the same update are in the same thread, 
      // we need to match them by updateId
      customerQuestions.forEach(item => {
        const questionUpdateId = item.question.updateId;
        const questionCreatedAt = item.question.createdAt || new Date(0);
        const relatedReplies = allReplies.filter(r => {
          const replyCreatedAt = r.createdAt || new Date(0);
          return r.updateId === questionUpdateId && replyCreatedAt > questionCreatedAt;
        });
        repliesByQuestion[item.question.id] = relatedReplies;
      });
    }

    return customerQuestions.map(item => {
      const userName = item.user?.firstName 
        ? `${item.user.firstName}${item.user.lastName ? ' ' + item.user.lastName : ''}`
        : 'Unknown Customer';

      return {
        id: item.question.id,
        message: item.question.message,
        createdAt: item.question.createdAt,
        authorRole: item.question.authorRole,
        orderId: item.order?.id || '',
        orderNumber: item.order?.orderNumber || '',
        customerName: userName,
        userId: item.user?.id || '',
        replies: repliesByQuestion[item.question.id] || [],
      };
    });
  }

  async createCustomerQuestionReply(replyData: CreateStageUpdateReplyRequest): Promise<StageUpdateReply> {
    return this.createStageUpdateReply(replyData);
  }

  async getStageUpdateReply(replyId: string): Promise<StageUpdateReply | undefined> {
    const [reply] = await db
      .select()
      .from(stageUpdateReplies)
      .where(eq(stageUpdateReplies.id, replyId))
      .limit(1);

    return reply;
  }

  async getManufacturingProcessWithDetails(id: string): Promise<(ManufacturingProcess & { 
    assignedManufacturer?: User | null;
    stages: (ManufacturingStage & { 
      updates: (StageUpdate & { photos: StageUpdatePhoto[]; replies: StageUpdateReply[] })[] 
    })[] 
  }) | undefined> {
    const processWithManufacturer = await this.getManufacturingProcessWithManufacturer(id);
    if (!processWithManufacturer) return undefined;

    const stages = await this.getManufacturingStages(id);
    const stagesWithUpdates = await Promise.all(
      stages.map(async (stage) => {
        const updates = await this.getStageUpdates(stage.id, true); // Include internal updates for full details
        return { ...stage, updates };
      })
    );

    return {
      ...processWithManufacturer,
      stages: stagesWithUpdates,
    };
  }

  // Manufacturer Profile operations
  async createManufacturerProfile(userId: string, profileData: CreateManufacturerProfileRequest): Promise<ManufacturerProfile> {
    const [profile] = await db
      .insert(manufacturerProfiles)
      .values({
        userId,
        ...profileData,
      })
      .returning();

    return profile;
  }

  async getManufacturerProfile(userId: string): Promise<ManufacturerProfile | undefined> {
    const [profile] = await db
      .select()
      .from(manufacturerProfiles)
      .where(eq(manufacturerProfiles.userId, userId));

    return profile;
  }

  async getManufacturerProfileById(id: string): Promise<ManufacturerProfile | undefined> {
    const [profile] = await db
      .select()
      .from(manufacturerProfiles)
      .where(eq(manufacturerProfiles.id, id));

    return profile;
  }

  async updateManufacturerProfile(id: string, updates: Partial<ManufacturerProfile>): Promise<ManufacturerProfile | undefined> {
    const [updatedProfile] = await db
      .update(manufacturerProfiles)
      .set({
        ...updates,
        updatedAt: new Date(),
      })
      .where(eq(manufacturerProfiles.id, id))
      .returning();

    return updatedProfile;
  }

  async approveManufacturer(id: string, adminUserId: string, notes?: string): Promise<ManufacturerProfile | undefined> {
    const now = new Date();

    // First update the manufacturer profile
    const [profile] = await db
      .update(manufacturerProfiles)
      .set({
        isApproved: true,
        approvedBy: adminUserId,
        approvedAt: now,
        notes: notes || null,
        rejectedBy: null,
        rejectedAt: null,
        rejectionReason: null,
        updatedAt: now,
      })
      .where(eq(manufacturerProfiles.id, id))
      .returning();

    if (profile) {
      // Update user status to active
      await db
        .update(users)
        .set({
          status: 'active',
          updatedAt: now,
        })
        .where(eq(users.id, profile.userId));
    }

    return profile;
  }

  async rejectManufacturer(id: string, adminUserId: string, reason: string, notes?: string): Promise<ManufacturerProfile | undefined> {
    const now = new Date();

    // First update the manufacturer profile
    const [profile] = await db
      .update(manufacturerProfiles)
      .set({
        isApproved: false,
        rejectedBy: adminUserId,
        rejectedAt: now,
        rejectionReason: reason,
        notes: notes || null,
        approvedBy: null,
        approvedAt: null,
        updatedAt: now,
      })
      .where(eq(manufacturerProfiles.id, id))
      .returning();

    if (profile) {
      // Update user status to suspended
      await db
        .update(users)
        .set({
          status: 'suspended',
          updatedAt: now,
        })
        .where(eq(users.id, profile.userId));
    }

    return profile;
  }

  async getPendingManufacturerApplications(): Promise<(ManufacturerProfile & { user: User })[]> {
    const applications = await db
      .select({
        profile: manufacturerProfiles,
        user: users,
      })
      .from(manufacturerProfiles)
      .innerJoin(users, eq(manufacturerProfiles.userId, users.id))
      .where(
        and(
          eq(manufacturerProfiles.isApproved, false),
          eq(users.status, 'pending_approval'),
          eq(users.role, 'manufacturer')
        )
      )
      .orderBy(desc(manufacturerProfiles.createdAt));

    return applications.map(item => ({
      ...item.profile,
      user: item.user,
    }));
  }

  async getApprovedManufacturers(): Promise<(ManufacturerProfile & { user: User })[]> {
    const manufacturers = await db
      .select({
        profile: manufacturerProfiles,
        user: users,
      })
      .from(manufacturerProfiles)
      .innerJoin(users, eq(manufacturerProfiles.userId, users.id))
      .where(
        and(
          eq(manufacturerProfiles.isApproved, true),
          eq(users.status, 'active'),
          eq(users.role, 'manufacturer')
        )
      )
      .orderBy(desc(manufacturerProfiles.approvedAt));

    return manufacturers.map(item => ({
      ...item.profile,
      user: item.user,
    }));
  }

  // Simple Manufacturer operations (direct admin creation)
  async createDirectManufacturer(manufacturerData: CreateManufacturerRequest, adminUserId: string): Promise<Manufacturer> {
    // Create the manufacturer record
    const [manufacturer] = await db
      .insert(manufacturers)
      .values({
        ...manufacturerData,
        createdBy: adminUserId,
      })
      .returning();

    // Also create a user account so the manufacturer can log in
    // Check if user already exists with this email
    const existingUser = await this.getUserByEmail(manufacturerData.email);
    if (!existingUser) {
      // Create user account with default password "password"
      const hashedPassword = await hashPassword("password");

      await db
        .insert(users)
        .values({
          id: manufacturer.id, // Use the manufacturer ID as the user ID for consistency
          email: manufacturerData.email,
          password: hashedPassword,
          firstName: manufacturerData.name.split(' ')[0] || manufacturerData.name,
          lastName: manufacturerData.name.split(' ').slice(1).join(' ') || '',
          role: 'manufacturer',
          emailVerified: true, // Auto-verify admin-created accounts
          status: 'active',
        });
    }

    return manufacturer;
  }

  async getDirectManufacturers(): Promise<Manufacturer[]> {
    const allManufacturers = await db
      .select()
      .from(manufacturers)
      .where(eq(manufacturers.isActive, true))
      .orderBy(desc(manufacturers.createdAt));

    return allManufacturers;
  }

  async getDirectManufacturer(id: string): Promise<Manufacturer | undefined> {
    const [manufacturer] = await db
      .select()
      .from(manufacturers)
      .where(eq(manufacturers.id, id));

    return manufacturer;
  }

  async updateDirectManufacturer(id: string, updates: UpdateManufacturerRequest): Promise<Manufacturer | undefined> {
    const [updatedManufacturer] = await db
      .update(manufacturers)
      .set({
        ...updates,
        updatedAt: new Date(),
      })
      .where(eq(manufacturers.id, id))
      .returning();

    return updatedManufacturer;
  }

  async deleteDirectManufacturer(id: string): Promise<boolean> {
    const [updatedManufacturer] = await db
      .update(manufacturers)
      .set({
        isActive: false,
        updatedAt: new Date(),
      })
      .where(eq(manufacturers.id, id))
      .returning();

    return !!updatedManufacturer;
  }

  // Customer Notifications implementation
  async createNotification(notificationData: InsertCustomerNotification): Promise<CustomerNotification> {
    const [notification] = await db
      .insert(customerNotifications)
      .values(notificationData)
      .returning();

    return notification;
  }

  async getNotifications(userId: string, isRead?: boolean): Promise<CustomerNotification[]> {
    const conditions = [eq(customerNotifications.userId, userId)];

    if (isRead !== undefined) {
      conditions.push(eq(customerNotifications.isRead, isRead));
    }

    const notifications = await db
      .select()
      .from(customerNotifications)
      .where(and(...conditions))
      .orderBy(desc(customerNotifications.createdAt));

    return notifications;
  }

  async markNotificationAsRead(notificationId: string, userId: string): Promise<boolean> {
    const [updated] = await db
      .update(customerNotifications)
      .set({
        isRead: true,
        readAt: new Date(),
      })
      .where(and(
        eq(customerNotifications.id, notificationId),
        eq(customerNotifications.userId, userId)
      ))
      .returning();

    return !!updated;
  }

  async markAllNotificationsAsRead(userId: string): Promise<boolean> {
    const result = await db
      .update(customerNotifications)
      .set({
        isRead: true,
        readAt: new Date(),
      })
      .where(and(
        eq(customerNotifications.userId, userId),
        eq(customerNotifications.isRead, false)
      ));

    return true;
  }

  async getUnreadNotificationCount(userId: string): Promise<number> {
    const [result] = await db
      .select({ count: sql<number>`count(*)` })
      .from(customerNotifications)
      .where(and(
        eq(customerNotifications.userId, userId),
        eq(customerNotifications.isRead, false)
      ));

    return result?.count || 0;
  }

  // Support Tickets operations
  async createSupportTicket(ticketData: CreateSupportTicketRequest, userId?: string, userRole?: string): Promise<SupportTicket> {
    const [ticket] = await db
      .insert(supportTickets)
      .values({
        ...ticketData,
        userId: userId || null,
        userRole: userRole || (userId ? 'customer' : 'guest'),
      })
      .returning();

    return ticket;
  }

  async getSupportTickets(options?: { userId?: string; status?: string; category?: string; assignedTo?: string }): Promise<SupportTicket[]> {
    const conditions = [];

    if (options?.userId) {
      conditions.push(eq(supportTickets.userId, options.userId));
    }
    if (options?.status) {
      conditions.push(sql`${supportTickets.status} = ${options.status}`);
    }
    if (options?.category) {
      conditions.push(sql`${supportTickets.category} = ${options.category}`);
    }
    if (options?.assignedTo) {
      conditions.push(eq(supportTickets.assignedTo, options.assignedTo));
    }

    const query = db
      .select()
      .from(supportTickets)
      .orderBy(desc(supportTickets.createdAt));

    const tickets = conditions.length > 0
      ? await query.where(and(...conditions))
      : await query;

    return tickets;
  }

  async getSupportTicket(id: string): Promise<SupportTicket | undefined> {
    const [ticket] = await db
      .select()
      .from(supportTickets)
      .where(eq(supportTickets.id, id));

    return ticket;
  }

  async updateSupportTicket(id: string, updates: UpdateSupportTicketRequest): Promise<SupportTicket | undefined> {
    const [ticket] = await db
      .update(supportTickets)
      .set({
        ...updates,
        updatedAt: new Date(),
      })
      .where(eq(supportTickets.id, id))
      .returning();

    return ticket;
  }

  async deleteSupportTicket(id: string): Promise<boolean> {
    const result = await db
      .delete(supportTickets)
      .where(eq(supportTickets.id, id));

    return true;
  }

  // FAQ operations
  async createFaq(faqData: CreateFaqRequest): Promise<Faq> {
    const [faq] = await db
      .insert(faqs)
      .values(faqData)
      .returning();

    return faq;
  }

  async getFaqs(options?: { category?: string; isActive?: boolean }): Promise<Faq[]> {
    const conditions = [];

    if (options?.category) {
      conditions.push(eq(faqs.category, options.category));
    }
    if (options?.isActive !== undefined) {
      conditions.push(eq(faqs.isActive, options.isActive));
    }

    const query = db
      .select()
      .from(faqs)
      .orderBy(faqs.displayOrder, desc(faqs.createdAt));

    const faqList = conditions.length > 0
      ? await query.where(and(...conditions))
      : await query;

    return faqList;
  }

  async getFaq(id: string): Promise<Faq | undefined> {
    const [faq] = await db
      .select()
      .from(faqs)
      .where(eq(faqs.id, id));

    return faq;
  }

  async updateFaq(id: string, updates: UpdateFaqRequest): Promise<Faq | undefined> {
    const [faq] = await db
      .update(faqs)
      .set({
        ...updates,
        updatedAt: new Date(),
      })
      .where(eq(faqs.id, id))
      .returning();

    return faq;
  }

  async deleteFaq(id: string): Promise<boolean> {
    const result = await db
      .delete(faqs)
      .where(eq(faqs.id, id));

    return true;
  }
}

export const storage = new DatabaseStorage();

