            { id: 'brass', name: 'Brass', price: 25 },
            { id: 'chrome', name: 'Chrome', price: 15 },
            { id: 'black', name: 'Matte Black', price: 20 },
            { id: 'nickel', name: 'Brushed Nickel', price: 30 },
          ]),
          defaultValue: 'brass',
