import { useState } from "react";
import { Dialog, DialogContent, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Camera, Download, X, ChevronLeft, ChevronRight } from "lucide-react";

interface Photo {
  id: string;
  url: string;
  description?: string;
  createdAt: string;
  width?: number;
  height?: number;
  blurhash?: string;
}

interface PhotoGridProps {
  photos: Photo[];
  className?: string;
  size?: "sm" | "md" | "lg";
  maxColumns?: number;
  showDescriptions?: boolean;
  onPhotoClick?: (photo: Photo, index: number) => void;
}

export function PhotoGrid({ 
  photos, 
  className, 
  size = "md",
  maxColumns = 4,
  showDescriptions = false,
  onPhotoClick
}: PhotoGridProps) {
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0);

  if (!photos || photos.length === 0) {
    return (
      <div 
        className={cn(
          "flex items-center justify-center py-8 text-muted-foreground border-2 border-dashed rounded-lg",
          className
        )}
        data-testid="photo-grid-empty"
      >
        <div className="text-center">
          <Camera className="h-8 w-8 mx-auto mb-2 opacity-50" />
          <p className="text-sm">No photos available</p>
        </div>
      </div>
    );
  }

  const getSizeClasses = () => {
    switch (size) {
      case "sm":
        return "h-16 w-16";
      case "md":
        return "h-24 w-24";
      case "lg":
        return "h-32 w-32";
      default:
        return "h-24 w-24";
    }
  };

  const getGridCols = () => {
    const cols = Math.min(photos.length, maxColumns);
    switch (cols) {
      case 1:
        return "grid-cols-1";
      case 2:
        return "grid-cols-2";
      case 3:
        return "grid-cols-3";
      default:
        return "grid-cols-4";
    }
  };

  const handlePhotoClick = (photo: Photo, index: number) => {
    if (onPhotoClick) {
      onPhotoClick(photo, index);
    } else {
      setCurrentPhotoIndex(index);
      setLightboxOpen(true);
    }
  };

  const nextPhoto = () => {
    setCurrentPhotoIndex((prev) => (prev + 1) % photos.length);
  };

  const prevPhoto = () => {
    setCurrentPhotoIndex((prev) => (prev - 1 + photos.length) % photos.length);
  };

  const formatDate = (date: string) => {
    return new Date(date).toLocaleDateString();
  };

  return (
    <>
      <div 
        className={cn(
          "grid gap-2",
          getGridCols(),
          className
        )}
        data-testid="photo-grid"
      >
        {photos.map((photo, index) => (
          <div 
            key={photo.id} 
            className={cn(
              "relative group overflow-hidden rounded-lg border bg-muted cursor-pointer transition-all hover:shadow-md",
              getSizeClasses()
            )}
            onClick={() => handlePhotoClick(photo, index)}
            data-testid={`photo-item-${photo.id}`}
          >
            <img
              src={photo.url}
              alt={photo.description || `Photo ${index + 1}`}
              className="h-full w-full object-cover transition-transform group-hover:scale-105"
              loading="lazy"
            />

            {/* Overlay on hover */}
            <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-colors flex items-center justify-center">
              <Camera className="h-4 w-4 text-white opacity-0 group-hover:opacity-100 transition-opacity" />
            </div>

            {/* Photo number indicator for multiple photos */}
            {photos.length > 1 && (
              <div className="absolute top-1 right-1 bg-black/50 text-white text-xs px-1 py-0.5 rounded">
                {index + 1}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Description list if enabled */}
      {showDescriptions && (
        <div className="mt-2 space-y-1">
          {photos.map((photo, index) => (
            photo.description && (
              <div key={photo.id} className="text-xs text-muted-foreground">
                <span className="font-medium">{index + 1}.</span> {photo.description}
              </div>
            )
          ))}
        </div>
      )}

      {/* Lightbox Modal */}
      <Dialog open={lightboxOpen} onOpenChange={setLightboxOpen}>
        <DialogContent className="max-w-4xl w-full h-[80vh] p-0" data-testid="photo-lightbox">
          <div className="relative h-full bg-black rounded-lg overflow-hidden">
            {/* Close button */}
            <Button
              variant="ghost"
              size="sm"
              className="absolute top-4 right-4 z-10 text-white hover:bg-white/20"
              onClick={() => setLightboxOpen(false)}
              data-testid="lightbox-close"
            >
              <X className="h-4 w-4" />
            </Button>

            {/* Navigation buttons */}
            {photos.length > 1 && (
              <>
                <Button
                  variant="ghost"
                  size="sm"
                  className="absolute left-4 top-1/2 -translate-y-1/2 z-10 text-white hover:bg-white/20"
                  onClick={prevPhoto}
                  data-testid="lightbox-prev"
                >
                  <ChevronLeft className="h-4 w-4" />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  className="absolute right-4 top-1/2 -translate-y-1/2 z-10 text-white hover:bg-white/20"
                  onClick={nextPhoto}
                  data-testid="lightbox-next"
                >
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </>
            )}

            {/* Current photo */}
            <div className="h-full flex items-center justify-center p-4">
              <img
                src={photos[currentPhotoIndex]?.url}
                alt={photos[currentPhotoIndex]?.description || `Photo ${currentPhotoIndex + 1}`}
                className="max-h-full max-w-full object-contain"
                data-testid={`lightbox-image-${currentPhotoIndex}`}
              />
            </div>

            {/* Photo info */}
            <div className="absolute bottom-0 left-0 right-0 bg-black/50 text-white p-4">
              <div className="flex items-center justify-between">
                <div>
                  {photos[currentPhotoIndex]?.description && (
                    <p className="text-sm font-medium" data-testid="lightbox-description">
                      {photos[currentPhotoIndex].description}
                    </p>
                  )}
                  <p className="text-xs text-gray-300" data-testid="lightbox-date">
                    {formatDate(photos[currentPhotoIndex]?.createdAt)}
                  </p>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs" data-testid="lightbox-counter">
                    {currentPhotoIndex + 1} of {photos.length}
                  </span>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-white hover:bg-white/20"
                    onClick={() => {
                      const link = document.createElement('a');
                      link.href = photos[currentPhotoIndex]?.url;
                      link.download = photos[currentPhotoIndex]?.description || `photo-${currentPhotoIndex + 1}`;
                      link.click();
                    }}
                    data-testid="lightbox-download"
                  >
                    <Download className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

client/src/pages/manufacturer-registrati.content:
import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Checkbox } from "@/components/ui/checkbox";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { Link, useLocation } from "wouter";
import { ArrowLeft, Building2, CheckCircle, AlertCircle } from "lucide-react";
import { manufacturerApplicationSchema, type ManufacturerApplicationRequest } from "@shared/schema";

export default function ManufacturerRegistration() {
  const [, setLocation] = useLocation();
  const [isSubmitted, setIsSubmitted] = useState(false);
  const { toast } = useToast();

  const form = useForm<ManufacturerApplicationRequest>({
    resolver: zodResolver(manufacturerApplicationSchema),
    defaultValues: {
      email: "",
      password: "",
      firstName: "",
      lastName: "",
      companyName: "",
      companyAddress: "",
      phone: "",
      experience: "",
      specialties: [],
      portfolioUrls: [],
      businessLicense: "",
      certifications: [],
      notes: "",
    },
  });

  const [specialties, setSpecialties] = useState<string[]>([]);
  const [portfolioUrls, setPortfolioUrls] = useState<string[]>([""]);
  const [certifications, setCertifications] = useState<string[]>([""]);

  const availableSpecialties = [
    "Teak Furniture",
    "Custom Woodworking", 
    "Fine Furniture",
    "Outdoor Furniture",
    "Modern Design",
    "Traditional Craftsmanship",
    "Restoration",
    "Carving & Detailing",
    "Finishing & Polish",
    "Upholstery Integration"
  ];

  const submitApplication = useMutation({
    mutationFn: async (data: ManufacturerApplicationRequest) => {
      const response = await apiRequest("POST", "/api/auth/manufacturer-application", data);
      return response.json();
    },
    onSuccess: () => {
      setIsSubmitted(true);
      toast({
        title: "Application Submitted",
        description: "Your manufacturer application has been submitted for review. You will receive an email notification once it's approved.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Application Failed",
        description: error.message || "Failed to submit application. Please try again.",
        variant: "destructive",
      });
    },
  });

  const onSubmit = (data: ManufacturerApplicationRequest) => {
    // Ensure specialties are validated
    if (specialties.length === 0) {
      toast({
        title: "Validation Error",
        description: "Please select at least one specialty.",
        variant: "destructive",
      });
      return;
    }

    // Submit with merged data
    submitApplication.mutate({
      ...data,
      specialties: specialties,
      portfolioUrls: portfolioUrls.filter(url => url.trim()),
      certifications: certifications.filter(cert => cert.trim()),
    });
  };

  const handleSpecialtyChange = (specialty: string, checked: boolean) => {
    if (checked) {
      setSpecialties(prev => [...prev, specialty]);
    } else {
      setSpecialties(prev => prev.filter(s => s !== specialty));
    }
  };

  const addPortfolioUrl = () => {
    setPortfolioUrls(prev => [...prev, ""]);
  };

  const updatePortfolioUrl = (index: number, value: string) => {
    setPortfolioUrls(prev => prev.map((url, i) => i === index ? value : url));
  };

  const removePortfolioUrl = (index: number) => {
    setPortfolioUrls(prev => prev.filter((_, i) => i !== index));
  };

  const addCertification = () => {
    setCertifications(prev => [...prev, ""]);
  };

  const updateCertification = (index: number, value: string) => {
    setCertifications(prev => prev.map((cert, i) => i === index ? value : cert));
  };

  const removeCertification = (index: number) => {
    setCertifications(prev => prev.filter((_, i) => i !== index));
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 flex items-center justify-center p-4">
        <Card className="w-full max-w-2xl">
          <CardContent className="pt-8 text-center">
            <CheckCircle className="h-16 w-16 text-green-600 mx-auto mb-4" />
            <h1 className="text-2xl font-bold text-green-800 mb-2">Application Submitted!</h1>
            <p className="text-muted-foreground mb-6">
              Thank you for your interest in becoming a Teak Theory manufacturing partner. 
              Your application has been submitted and is under review.
            </p>
            <div className="space-y-2 text-sm text-muted-foreground mb-6">
              <p>• You will receive an email confirmation shortly</p>
              <p>• Our team will review your application within 3-5 business days</p>
              <p>• You'll be notified via email once your application is approved or if we need additional information</p>
            </div>
            <div className="flex gap-4 justify-center">
              <Button asChild>
                <Link href="/" data-testid="button-go-home">
                  Return Home
                </Link>
              </Button>
              <Button variant="outline" asChild>
                <Link href="/login" data-testid="button-go-login">
                  Sign In
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-green-50 to-blue-50 py-8 px-4">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6">
          <Button variant="ghost" asChild className="mb-4">
            <Link href="/" data-testid="button-back-home">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Home
            </Link>
          </Button>

          <div className="text-center">
            <Building2 className="h-12 w-12 text-green-600 mx-auto mb-4" />
            <h1 className="text-3xl font-bold mb-2" data-testid="text-registration-title">
              Become a Manufacturing Partner
            </h1>
            <p className="text-muted-foreground max-w-2xl mx-auto">
              Join our network of skilled craftsmen and help bring premium teak furniture to customers worldwide. 
              Complete the application below to get started.
            </p>
          </div>
        </div>

        <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
          {/* Personal Information */}
          <Card>
            <CardHeader>
              <CardTitle>Personal Information</CardTitle>
              <CardDescription>
                Your personal details for account creation
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <Label htmlFor="firstName">First Name *</Label>
                  <Input
                    id="firstName"
                    {...form.register("firstName")}
                    data-testid="input-first-name"
                    className={form.formState.errors.firstName ? "border-red-500" : ""}
                  />
                  {form.formState.errors.firstName && (
                    <p className="text-sm text-red-500 mt-1">{form.formState.errors.firstName.message}</p>
                  )}
                </div>

                <div>
                  <Label htmlFor="lastName">Last Name *</Label>
                  <Input
                    id="lastName"
                    {...form.register("lastName")}
                    data-testid="input-last-name"
                    className={form.formState.errors.lastName ? "border-red-500" : ""}
                  />
                  {form.formState.errors.lastName && (
                    <p className="text-sm text-red-500 mt-1">{form.formState.errors.lastName.message}</p>
                  )}
                </div>
              </div>

              <div>
                <Label htmlFor="email">Email Address *</Label>
                <Input
                  id="email"
                  type="email"
                  {...form.register("email")}
                  data-testid="input-email"
                  className={form.formState.errors.email ? "border-red-500" : ""}
                />
                {form.formState.errors.email && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.email.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="password">Password *</Label>
                <Input
                  id="password"
                  type="password"
                  {...form.register("password")}
                  data-testid="input-password"
                  className={form.formState.errors.password ? "border-red-500" : ""}
                />
                {form.formState.errors.password && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.password.message}</p>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Company Information */}
          <Card>
            <CardHeader>
              <CardTitle>Company Information</CardTitle>
              <CardDescription>
                Details about your manufacturing business
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="companyName">Company Name *</Label>
                <Input
                  id="companyName"
                  {...form.register("companyName")}
                  data-testid="input-company-name"
                  className={form.formState.errors.companyName ? "border-red-500" : ""}
                />
                {form.formState.errors.companyName && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.companyName.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="companyAddress">Company Address *</Label>
                <Textarea
                  id="companyAddress"
                  {...form.register("companyAddress")}
                  data-testid="input-company-address"
                  className={form.formState.errors.companyAddress ? "border-red-500" : ""}
                  rows={3}
                />
                {form.formState.errors.companyAddress && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.companyAddress.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="phone">Phone Number *</Label>
                <Input
                  id="phone"
                  {...form.register("phone")}
                  data-testid="input-phone"
                  className={form.formState.errors.phone ? "border-red-500" : ""}
                />
                {form.formState.errors.phone && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.phone.message}</p>
                )}
              </div>

              <div>
                <Label htmlFor="businessLicense">Business License Number</Label>
                <Input
                  id="businessLicense"
                  {...form.register("businessLicense")}
                  data-testid="input-business-license"
                />
              </div>
            </CardContent>
          </Card>

          {/* Experience and Expertise */}
          <Card>
            <CardHeader>
              <CardTitle>Experience & Expertise</CardTitle>
              <CardDescription>
                Tell us about your manufacturing experience and specializations
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label htmlFor="experience">Experience Description *</Label>
                <Textarea
                  id="experience"
                  {...form.register("experience")}
                  data-testid="input-experience"
                  className={form.formState.errors.experience ? "border-red-500" : ""}
                  rows={4}
                  placeholder="Describe your years of experience, types of furniture manufactured, team size, production capacity, etc."
                />
                {form.formState.errors.experience && (
                  <p className="text-sm text-red-500 mt-1">{form.formState.errors.experience.message}</p>
                )}
              </div>

              <div>
                <Label>Specialties & Expertise *</Label>
                <div className="grid grid-cols-2 gap-2 mt-2">
                  {availableSpecialties.map((specialty) => (
                    <div key={specialty} className="flex items-center space-x-2">
                      <Checkbox
                        id={`specialty-${specialty}`}
                        checked={specialties.includes(specialty)}
                        onCheckedChange={(checked) => handleSpecialtyChange(specialty, checked === true)}
                        data-testid={`checkbox-specialty-${specialty.toLowerCase().replace(/\s+/g, '-')}`}
                      />
                      <Label 
                        htmlFor={`specialty-${specialty}`} 
                        className="text-sm font-normal"
                      >
                        {specialty}
                      </Label>
                    </div>
                  ))}
                </div>
                {specialties.length === 0 && (
                  <p className="text-sm text-red-500 mt-1">Please select at least one specialty</p>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Portfolio & Certifications */}
          <Card>
            <CardHeader>
              <CardTitle>Portfolio & Certifications</CardTitle>
              <CardDescription>
                Showcase your work and qualifications (optional)
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <div className="flex justify-between items-center mb-2">
                  <Label>Portfolio URLs</Label>
                  <Button type="button" variant="outline" size="sm" onClick={addPortfolioUrl}>
                    Add URL
                  </Button>
                </div>
                {portfolioUrls.map((url, index) => (
                  <div key={index} className="flex gap-2">
                    <Input
                      value={url}
                      onChange={(e) => updatePortfolioUrl(index, e.target.value)}
                      placeholder="https://your-portfolio.com"
                      data-testid={`input-portfolio-url-${index}`}
                    />
                    {portfolioUrls.length > 1 && (
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => removePortfolioUrl(index)}
                      >
                        Remove
                      </Button>
                    )}
                  </div>
                ))}
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <Label>Certifications</Label>
                  <Button type="button" variant="outline" size="sm" onClick={addCertification}>
                    Add Certification
                  </Button>
                </div>
                {certifications.map((cert, index) => (
                  <div key={index} className="flex gap-2">
                    <Input
                      value={cert}
                      onChange={(e) => updateCertification(index, e.target.value)}
                      placeholder="e.g., ISO 9001, FSC Certified, etc."
                      data-testid={`input-certification-${index}`}
                    />
                    {certifications.length > 1 && (
                      <Button
                        type="button"
                        variant="outline"
                        size="sm"
                        onClick={() => removeCertification(index)}
                      >
                        Remove
                      </Button>
                    )}
                  </div>
                ))}
              </div>

              <div>
                <Label htmlFor="notes">Additional Notes</Label>
                <Textarea
                  id="notes"
                  {...form.register("notes")}
                  data-testid="input-notes"
                  rows={3}
                  placeholder="Any additional information you'd like to share about your capabilities, equipment, or experience..."
                />
              </div>
            </CardContent>
          </Card>

          {/* Submit */}
          <Card>
            <CardContent className="pt-6">
              <div className="flex items-start gap-3 mb-6">
                <AlertCircle className="h-5 w-5 text-amber-600 mt-0.5" />
                <div className="text-sm text-muted-foreground">
                  <p className="font-medium mb-2">Important Information:</p>
                  <ul className="space-y-1 text-xs">
                    <li>• All applications are reviewed by our quality team</li>
                    <li>• Approval typically takes 3-5 business days</li>
                    <li>• You'll receive email notifications about your application status</li>
                    <li>• Only approved manufacturers can access the manufacturing portal</li>
                  </ul>
                </div>
              </div>

              <Button 
                type="submit" 
                className="w-full" 
                disabled={submitApplication.isPending}
                data-testid="button-submit-application"
              >
                {submitApplication.isPending ? "Submitting Application..." : "Submit Application"}
              </Button>

              <div className="text-center mt-4">
                <p className="text-sm text-muted-foreground">
                  Already have an account?{" "}
                  <Link href="/login" className="text-primary hover:underline">
                    Sign in here
                  </Link>
                </p>
              </div>
            </CardContent>
          </Card>
        </form>
      </div>
    </div>
  );
}

client/src/pages/admin/users.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle, AlertDialogTrigger } from "@/components/ui/alert-dialog";
import { Switch } from "@/components/ui/switch";
import { Search, Edit2, Users, Trash2 } from "lucide-react";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Skeleton } from "@/components/ui/skeleton";

interface User {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  isAdmin: boolean;
  status: string;
  createdAt?: string;
}

interface UsersResponse {
  users: User[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

export default function AdminUsers() {
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [deletingUser, setDeletingUser] = useState<User | null>(null);
  const { toast } = useToast();
  const limit = 20;

  const { data: usersData, isLoading } = useQuery<UsersResponse>({
    queryKey: ["/api/admin/users", page, search, statusFilter],
    queryFn: async () => {
      const params = new URLSearchParams({
        page: page.toString(),
        limit: limit.toString(),
      });

      if (search) params.append("search", search);
      if (statusFilter !== "all") params.append("status", statusFilter);

      const response = await apiRequest("GET", `/api/admin/users?${params.toString()}`);
      return response.json();
    },
  });

  const updateUserMutation = useMutation({
    mutationFn: async ({ userId, data }: { userId: string; data: Partial<User> }) => {
      const response = await apiRequest("PATCH", `/api/admin/users/${userId}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      toast({
        title: "Success",
        description: "User updated successfully",
      });
      setIsEditDialogOpen(false);
      setEditingUser(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update user",
        variant: "destructive",
      });
    },
  });

  const deleteUserMutation = useMutation({
    mutationFn: async (userId: string) => {
      const response = await apiRequest("DELETE", `/api/admin/users/${userId}`);
      // Handle empty response or check content type before parsing JSON
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        return response.json();
      }
      return { success: true }; // Default success response
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/users"] });
      toast({
        title: "Success",
        description: "User deleted successfully",
      });
      setDeletingUser(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete user",
        variant: "destructive",
      });
    },
  });

  const handleEditUser = (user: User) => {
    setEditingUser(user);
    setIsEditDialogOpen(true);
  };

  const handleUpdateUser = (data: Partial<User>) => {
    if (editingUser) {
      updateUserMutation.mutate({ userId: editingUser.id, data });
    }
  };

  const handleDeleteUser = (user: User) => {
    setDeletingUser(user);
  };

  const confirmDeleteUser = () => {
    if (deletingUser) {
      deleteUserMutation.mutate(deletingUser.id);
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "active":
        return <Badge variant="default" className="bg-green-100 text-green-800">Active</Badge>;
      case "inactive":
        return <Badge variant="secondary" className="bg-gray-100 text-gray-800">Inactive</Badge>;
      case "suspended":
        return <Badge variant="destructive">Suspended</Badge>;
      default:
        return <Badge variant="outline">{status}</Badge>;
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight" data-testid="text-users-title">Users</h1>
          <p className="text-muted-foreground" data-testid="text-users-description">
            Manage user accounts and permissions
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Users className="h-8 w-8 text-muted-foreground" />
          <span className="text-2xl font-bold" data-testid="text-total-users">
            {usersData?.total || 0}
          </span>
        </div>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
          <CardDescription>Filter and search users</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex gap-4">
            <div className="flex-1">
              <Label htmlFor="search">Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  id="search"
                  placeholder="Search by email or name..."
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  className="pl-8"
                  data-testid="input-search-users"
                />
              </div>
            </div>
            <div>
              <Label htmlFor="status">Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger data-testid="select-status-filter">
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All statuses</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                  <SelectItem value="suspended">Suspended</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Users Table */}
      <Card>
        <CardHeader>
          <CardTitle>Users</CardTitle>
          <CardDescription>
            {usersData ? `${usersData.users.length} of ${usersData.total} users` : "Loading users..."}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="space-y-4">
              {[...Array(5)].map((_, i) => (
                <div key={i} className="flex items-center justify-between p-4 border rounded">
                  <div className="space-y-2">
                    <Skeleton className="h-4 w-48" />
                    <Skeleton className="h-3 w-32" />
                  </div>
                  <div className="flex gap-2">
                    <Skeleton className="h-6 w-16" />
                    <Skeleton className="h-8 w-16" />
                  </div>
                </div>
              ))}
            </div>
          ) : usersData?.users.length ? (
            <div className="space-y-4">
              {usersData.users.map((user) => (
                <div key={user.id} className="flex items-center justify-between p-4 border rounded hover:bg-muted/50" data-testid={`user-row-${user.id}`}>
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="font-medium" data-testid={`text-user-name-${user.id}`}>
                        {user.firstName} {user.lastName}
                      </span>
                      {user.isAdmin && (
                        <Badge variant="default" className="bg-blue-100 text-blue-800">Admin</Badge>
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground" data-testid={`text-user-email-${user.id}`}>
                      {user.email}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    {getStatusBadge(user.status)}
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleEditUser(user)}
                      data-testid={`button-edit-user-${user.id}`}
                    >
                      <Edit2 className="h-4 w-4 mr-1" />
                      Edit
                    </Button>
                    <AlertDialog>
                      <AlertDialogTrigger asChild>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDeleteUser(user)}
                          data-testid={`button-delete-user-${user.id}`}
                          className="text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="h-4 w-4 mr-1" />
                          Delete
                        </Button>
                      </AlertDialogTrigger>
                      <AlertDialogContent data-testid="dialog-delete-user">
                        <AlertDialogHeader>
                          <AlertDialogTitle>Delete User</AlertDialogTitle>
                          <AlertDialogDescription>
                            Are you sure you want to delete {user.firstName} {user.lastName}? This action cannot be undone and will permanently remove their account and all associated data.
                          </AlertDialogDescription>
                        </AlertDialogHeader>
                        <AlertDialogFooter>
                          <AlertDialogCancel data-testid="button-cancel-delete">Cancel</AlertDialogCancel>
                          <AlertDialogAction
                            onClick={confirmDeleteUser}
                            disabled={deleteUserMutation.isPending}
                            data-testid="button-confirm-delete"
                            className="bg-red-600 hover:bg-red-700"
                          >
                            {deleteUserMutation.isPending ? "Deleting..." : "Delete User"}
                          </AlertDialogAction>
                        </AlertDialogFooter>
                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </div>
              ))}

              {/* Pagination */}
              {usersData.totalPages > 1 && (
                <div className="flex justify-center gap-2 mt-6">
                  <Button
                    variant="outline"
                    onClick={() => setPage(page - 1)}
                    disabled={page === 1}
                    data-testid="button-prev-page"
                  >
                    Previous
                  </Button>
                  <span className="flex items-center px-4" data-testid="text-page-info">
                    Page {page} of {usersData.totalPages}
                  </span>
                  <Button
                    variant="outline"
                    onClick={() => setPage(page + 1)}
                    disabled={page === usersData.totalPages}
                    data-testid="button-next-page"
                  >
                    Next
                  </Button>
                </div>
              )}
            </div>
          ) : (
            <div className="text-center py-8">
              <p className="text-muted-foreground" data-testid="text-no-users">No users found</p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Edit User Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent data-testid="dialog-edit-user">
          <DialogHeader>
            <DialogTitle>Edit User</DialogTitle>
            <DialogDescription>
              Update user information and permissions
            </DialogDescription>
          </DialogHeader>

          {editingUser && (
            <div className="space-y-4 py-4">
              <div className="space-y-2">
                <Label htmlFor="edit-email">Email</Label>
                <Input
                  id="edit-email"
                  value={editingUser.email}
                  onChange={(e) => setEditingUser({ ...editingUser, email: e.target.value })}
                  data-testid="input-edit-email"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="edit-first-name">First Name</Label>
                  <Input
                    id="edit-first-name"
                    value={editingUser.firstName}
                    onChange={(e) => setEditingUser({ ...editingUser, firstName: e.target.value })}
                    data-testid="input-edit-first-name"
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="edit-last-name">Last Name</Label>
                  <Input
                    id="edit-last-name"
                    value={editingUser.lastName}
                    onChange={(e) => setEditingUser({ ...editingUser, lastName: e.target.value })}
                    data-testid="input-edit-last-name"
                  />
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="edit-status">Status</Label>
                <Select value={editingUser.status} onValueChange={(value) => setEditingUser({ ...editingUser, status: value })}>
                  <SelectTrigger data-testid="select-edit-status">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="inactive">Inactive</SelectItem>
                    <SelectItem value="suspended">Suspended</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="flex items-center justify-between">
                <Label htmlFor="edit-admin">Admin Access</Label>
                <Switch
                  id="edit-admin"
                  checked={editingUser.isAdmin}
                  onCheckedChange={(checked) => setEditingUser({ ...editingUser, isAdmin: checked })}
                  data-testid="switch-edit-admin"
                />
              </div>
            </div>
          )}

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditDialogOpen(false)} data-testid="button-cancel-edit">
              Cancel
            </Button>
            <Button 
              onClick={() => handleUpdateUser(editingUser!)}
              disabled={updateUserMutation.isPending}
              data-testid="button-save-user"
            >
              {updateUserMutation.isPending ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/components/ui/chart.tsx.content:
"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"

import { cn } from "@/lib/utils"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

export type ChartConfig = {
  [k in string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

const ChartContainer = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> & {
    config: ChartConfig
    children: React.ComponentProps<
      typeof RechartsPrimitive.ResponsiveContainer
    >["children"]
  }
>(({ id, className, children, config, ...props }, ref) => {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-chart={chartId}
        ref={ref}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-none [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-none [&_.recharts-surface]:outline-none",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
})
ChartContainer.displayName = "Chart"

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme || config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

const ChartTooltipContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
    React.ComponentProps<"div"> & {
      hideLabel?: boolean
      hideIndicator?: boolean
      indicator?: "line" | "dot" | "dashed"
      nameKey?: string
      labelKey?: string
    }
>(
  (
    {
      active,
      payload,
      className,
      indicator = "dot",
      hideLabel = false,
      hideIndicator = false,
      label,
      labelFormatter,
      labelClassName,
      formatter,
      color,
      nameKey,
      labelKey,
    },
    ref
  ) => {
    const { config } = useChart()

    const tooltipLabel = React.useMemo(() => {
      if (hideLabel || !payload?.length) {
        return null
      }

      const [item] = payload
      const key = `${labelKey || item?.dataKey || item?.name || "value"}`
      const itemConfig = getPayloadConfigFromPayload(config, item, key)
      const value =
        !labelKey && typeof label === "string"
          ? config[label as keyof typeof config]?.label || label
          : itemConfig?.label

      if (labelFormatter) {
        return (
          <div className={cn("font-medium", labelClassName)}>
            {labelFormatter(value, payload)}
          </div>
        )
      }

      if (!value) {
        return null
      }

      return <div className={cn("font-medium", labelClassName)}>{value}</div>
    }, [
      label,
      labelFormatter,
      payload,
      hideLabel,
      labelClassName,
      config,
      labelKey,
    ])

    if (!active || !payload?.length) {
      return null
    }

    const nestLabel = payload.length === 1 && indicator !== "dot"

    return (
      <div
        ref={ref}
        className={cn(
          "grid min-w-[8rem] items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
          className
        )}
      >
        {!nestLabel ? tooltipLabel : null}
        <div className="grid gap-1.5">
          {payload.map((item, index) => {
            const key = `${nameKey || item.name || item.dataKey || "value"}`
            const itemConfig = getPayloadConfigFromPayload(config, item, key)
            const indicatorColor = color || item.payload.fill || item.color

            return (
              <div
                key={item.dataKey}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-[--color-border] bg-[--color-bg]",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label || item.name}
                        </span>
                      </div>
                      {item.value && (
                        <span className="font-mono font-medium tabular-nums text-foreground">
                          {item.value.toLocaleString()}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
        </div>
      </div>
    )
  }
)
ChartTooltipContent.displayName = "ChartTooltip"

const ChartLegend = RechartsPrimitive.Legend

const ChartLegendContent = React.forwardRef<
  HTMLDivElement,
  React.ComponentProps<"div"> &
    Pick<RechartsPrimitive.LegendProps, "payload" | "verticalAlign"> & {
      hideIcon?: boolean
      nameKey?: string
    }
>(
  (
    { className, hideIcon = false, payload, verticalAlign = "bottom", nameKey },
    ref
  ) => {
    const { config } = useChart()

    if (!payload?.length) {
      return null
    }

    return (
      <div
        ref={ref}
        className={cn(
          "flex items-center justify-center gap-4",
          verticalAlign === "top" ? "pb-3" : "pt-3",
          className
        )}
      >
        {payload.map((item) => {
          const key = `${nameKey || item.dataKey || "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)

          return (
            <div
              key={item.value}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-[2px]"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          )
        })}
      </div>
    )
  }
)
ChartLegendContent.displayName = "ChartLegend"

// Helper to extract item config from a payload.
function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config
    ? config[configLabelKey]
    : config[key as keyof typeof config]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

client/src/pages/admin/support.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { Mail, Phone, Calendar, User, MessageSquare, Plus, Trash2, Edit } from "lucide-react";
import type { SupportTicket, Faq, CreateFaqRequest, UpdateFaqRequest } from "@shared/schema";

const categoryLabels: Record<string, string> = {
  sales: "Sales Inquiry",
  customer_support: "Customer Support",
  manufacturing: "Manufacturing Question",
  technical: "Technical Issue",
  general: "General Question",
};

const statusColors: Record<string, string> = {
  open: "bg-blue-500",
  in_progress: "bg-yellow-500",
  resolved: "bg-green-500",
  closed: "bg-gray-500",
};

const priorityColors: Record<string, string> = {
  low: "bg-gray-400",
  medium: "bg-blue-400",
  high: "bg-orange-400",
  urgent: "bg-red-500",
};

export default function AdminSupport() {
  const { toast } = useToast();
  const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [categoryFilter, setCategoryFilter] = useState<string>("all");
  const [showFaqDialog, setShowFaqDialog] = useState(false);
  const [editingFaq, setEditingFaq] = useState<Faq | null>(null);
  const [faqQuestion, setFaqQuestion] = useState("");
  const [faqAnswer, setFaqAnswer] = useState("");

  const { data: ticketsData, isLoading } = useQuery<{ tickets: SupportTicket[] }>({
    queryKey: ["/api/support/all", statusFilter, categoryFilter],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (statusFilter !== "all") params.append("status", statusFilter);
      if (categoryFilter !== "all") params.append("category", categoryFilter);
      const url = `/api/support/all${params.toString() ? `?${params.toString()}` : ""}`;
      const response = await apiRequest("GET", url);
      return await response.json();
    },
  });

  const { data: faqsData } = useQuery<{ faqs: Faq[] }>({
    queryKey: ["/api/faqs/all"],
  });

  const updateTicketMutation = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: any }) => {
      const response = await apiRequest("PATCH", `/api/support/${id}`, updates);
      return await response.json();
    },
    onSuccess: () => {
      toast({
        title: "Ticket updated",
        description: "Support ticket has been updated successfully.",
      });
      queryClient.invalidateQueries({ queryKey: ["/api/support/all"] });
      setSelectedTicket(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update ticket",
        variant: "destructive",
      });
    },
  });

  const createFaqMutation = useMutation({
    mutationFn: async (data: CreateFaqRequest) => {
      const response = await apiRequest("POST", "/api/faqs", data);
      return await response.json();
    },
    onSuccess: () => {
      toast({ title: "FAQ created successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/faqs/all"] });
      setShowFaqDialog(false);
      setFaqQuestion("");
      setFaqAnswer("");
    },
  });

  const updateFaqMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: UpdateFaqRequest }) => {
      const response = await apiRequest("PATCH", `/api/faqs/${id}`, data);
      return await response.json();
    },
    onSuccess: () => {
      toast({ title: "FAQ updated successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/faqs/all"] });
      setEditingFaq(null);
      setShowFaqDialog(false);
      setFaqQuestion("");
      setFaqAnswer("");
    },
  });

  const deleteFaqMutation = useMutation({
    mutationFn: async (id: string) => {
      const response = await apiRequest("DELETE", `/api/faqs/${id}`);
      return await response.json();
    },
    onSuccess: () => {
      toast({ title: "FAQ deleted successfully" });
      queryClient.invalidateQueries({ queryKey: ["/api/faqs/all"] });
    },
  });

  const handleSaveFaq = () => {
    if (!faqQuestion || !faqAnswer) {
      toast({ title: "Please fill in all fields", variant: "destructive" });
      return;
    }

    if (editingFaq) {
      updateFaqMutation.mutate({ id: editingFaq.id, data: { question: faqQuestion, answer: faqAnswer } });
    } else {
      createFaqMutation.mutate({ question: faqQuestion, answer: faqAnswer, category: "general", isActive: true });
    }
  };

  const tickets = ticketsData?.tickets || [];

  const ticketsByStatus = {
    open: tickets.filter(t => t.status === "open"),
    in_progress: tickets.filter(t => t.status === "in_progress"),
    resolved: tickets.filter(t => t.status === "resolved"),
    closed: tickets.filter(t => t.status === "closed"),
  };

  const handleUpdateStatus = (ticketId: string, status: string) => {
    updateTicketMutation.mutate({
      id: ticketId,
      updates: { status },
    });
  };

  const handleUpdatePriority = (ticketId: string, priority: string) => {
    updateTicketMutation.mutate({
      id: ticketId,
      updates: { priority },
    });
  };

  const getStatusBadge = (status: string) => (
    <Badge className={statusColors[status] || "bg-gray-500"} data-testid={`badge-status-${status}`}>
      {status.replace("_", " ")}
    </Badge>
  );

  const getPriorityBadge = (priority: string) => (
    <Badge className={priorityColors[priority] || "bg-gray-400"} data-testid={`badge-priority-${priority}`}>
      {priority}
    </Badge>
  );

  if (isLoading) {
    return (
      <div className="container mx-auto p-6">
        <div className="flex items-center justify-center h-64">
          <div className="text-muted-foreground">Loading support tickets...</div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6">
      <div className="mb-6">
        <h1 className="text-3xl font-bold mb-2" data-testid="heading-support-center">Support Center</h1>
        <p className="text-muted-foreground">Manage and respond to customer support requests</p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <Card data-testid="card-stat-open">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Open Tickets</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{ticketsByStatus.open.length}</div>
          </CardContent>
        </Card>

        <Card data-testid="card-stat-in-progress">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">In Progress</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{ticketsByStatus.in_progress.length}</div>
          </CardContent>
        </Card>

        <Card data-testid="card-stat-resolved">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Resolved</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{ticketsByStatus.resolved.length}</div>
          </CardContent>
        </Card>

        <Card data-testid="card-stat-closed">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">Closed</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{ticketsByStatus.closed.length}</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <div className="flex gap-4 mb-6">
        <div className="flex-1">
          <Label htmlFor="status-filter" className="mb-2 block">Status Filter</Label>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger id="status-filter" data-testid="select-status-filter">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Statuses</SelectItem>
              <SelectItem value="open">Open</SelectItem>
              <SelectItem value="in_progress">In Progress</SelectItem>
              <SelectItem value="resolved">Resolved</SelectItem>
              <SelectItem value="closed">Closed</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="flex-1">
          <Label htmlFor="category-filter" className="mb-2 block">Category Filter</Label>
          <Select value={categoryFilter} onValueChange={setCategoryFilter}>
            <SelectTrigger id="category-filter" data-testid="select-category-filter">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              <SelectItem value="sales">Sales Inquiry</SelectItem>
              <SelectItem value="customer_support">Customer Support</SelectItem>
              <SelectItem value="manufacturing">Manufacturing Question</SelectItem>
              <SelectItem value="technical">Technical Issue</SelectItem>
              <SelectItem value="general">General Question</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Tickets by Status Tabs */}
      <Tabs defaultValue="all" className="w-full">
        <TabsList className="grid w-full grid-cols-5">
          <TabsTrigger value="all">All ({tickets.length})</TabsTrigger>
          <TabsTrigger value="open">Open ({ticketsByStatus.open.length})</TabsTrigger>
          <TabsTrigger value="in_progress">In Progress ({ticketsByStatus.in_progress.length})</TabsTrigger>
          <TabsTrigger value="resolved">Resolved ({ticketsByStatus.resolved.length})</TabsTrigger>
          <TabsTrigger value="closed">Closed ({ticketsByStatus.closed.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="all" className="mt-6">
          <TicketList 
            tickets={tickets}
            onSelectTicket={setSelectedTicket}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePriority={handleUpdatePriority}
            getStatusBadge={getStatusBadge}
            getPriorityBadge={getPriorityBadge}
          />
        </TabsContent>

        <TabsContent value="open" className="mt-6">
          <TicketList 
            tickets={ticketsByStatus.open}
            onSelectTicket={setSelectedTicket}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePriority={handleUpdatePriority}
            getStatusBadge={getStatusBadge}
            getPriorityBadge={getPriorityBadge}
          />
        </TabsContent>

        <TabsContent value="in_progress" className="mt-6">
          <TicketList 
            tickets={ticketsByStatus.in_progress}
            onSelectTicket={setSelectedTicket}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePriority={handleUpdatePriority}
            getStatusBadge={getStatusBadge}
            getPriorityBadge={getPriorityBadge}
          />
        </TabsContent>

        <TabsContent value="resolved" className="mt-6">
          <TicketList 
            tickets={ticketsByStatus.resolved}
            onSelectTicket={setSelectedTicket}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePriority={handleUpdatePriority}
            getStatusBadge={getStatusBadge}
            getPriorityBadge={getPriorityBadge}
          />
        </TabsContent>

        <TabsContent value="closed" className="mt-6">
          <TicketList 
            tickets={ticketsByStatus.closed}
            onSelectTicket={setSelectedTicket}
            onUpdateStatus={handleUpdateStatus}
            onUpdatePriority={handleUpdatePriority}
            getStatusBadge={getStatusBadge}
            getPriorityBadge={getPriorityBadge}
          />
        </TabsContent>
      </Tabs>

      {/* FAQ Management Section */}
      <Card className="mt-8">
        <CardHeader>
          <div className="flex justify-between items-center">
            <div>
              <CardTitle>Manage FAQs</CardTitle>
              <CardDescription>Create and manage frequently asked questions</CardDescription>
            </div>
            <Button onClick={() => { setEditingFaq(null); setFaqQuestion(""); setFaqAnswer(""); setShowFaqDialog(true); }} data-testid="button-add-faq">
              <Plus className="h-4 w-4 mr-2" /> Add FAQ
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {faqsData?.faqs && faqsData.faqs.length > 0 ? (
              faqsData.faqs.map((faq) => (
                <Card key={faq.id} className="p-4">
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <h3 className="font-semibold mb-2">{faq.question}</h3>
                      <p className="text-sm text-muted-foreground">{faq.answer}</p>
                      <div className="mt-2 flex gap-2">
                        <Badge variant={faq.isActive ? "default" : "secondary"}>{faq.isActive ? "Active" : "Inactive"}</Badge>
                        {faq.category && <Badge variant="outline">{faq.category}</Badge>}
                      </div>
                    </div>
                    <div className="flex gap-2 ml-4">
                      <Button size="sm" variant="outline" onClick={() => { setEditingFaq(faq); setFaqQuestion(faq.question); setFaqAnswer(faq.answer); setShowFaqDialog(true); }} data-testid={`button-edit-faq-${faq.id}`}>
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button size="sm" variant="destructive" onClick={() => deleteFaqMutation.mutate(faq.id)} data-testid={`button-delete-faq-${faq.id}`}>
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </Card>
              ))
            ) : (
              <p className="text-center text-muted-foreground py-8">No FAQs created yet. Click "Add FAQ" to create one.</p>
            )}
          </div>
        </CardContent>
      </Card>

      {/* FAQ Dialog */}
      <Dialog open={showFaqDialog} onOpenChange={setShowFaqDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>{editingFaq ? "Edit FAQ" : "Add New FAQ"}</DialogTitle>
            <DialogDescription>Fill in the question and answer for the FAQ</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 mt-4">
            <div>
              <Label htmlFor="faq-question">Question</Label>
              <Input id="faq-question" value={faqQuestion} onChange={(e) => setFaqQuestion(e.target.value)} placeholder="Enter the question" data-testid="input-faq-question" />
            </div>
            <div>
              <Label htmlFor="faq-answer">Answer</Label>
              <Textarea id="faq-answer" value={faqAnswer} onChange={(e) => setFaqAnswer(e.target.value)} placeholder="Enter the answer" rows={4} data-testid="input-faq-answer" />
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => setShowFaqDialog(false)}>Cancel</Button>
              <Button onClick={handleSaveFaq} data-testid="button-save-faq">{editingFaq ? "Update" : "Create"} FAQ</Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Ticket Detail Dialog */}
      {selectedTicket && (
        <TicketDetailDialog 
          ticket={selectedTicket}
          open={!!selectedTicket}
          onClose={() => setSelectedTicket(null)}
          onUpdateStatus={handleUpdateStatus}
          onUpdatePriority={handleUpdatePriority}
          getStatusBadge={getStatusBadge}
          getPriorityBadge={getPriorityBadge}
        />
      )}
    </div>
  );
}

interface TicketListProps {
  tickets: SupportTicket[];
  onSelectTicket: (ticket: SupportTicket) => void;
  onUpdateStatus: (id: string, status: string) => void;
  onUpdatePriority: (id: string, priority: string) => void;
  getStatusBadge: (status: string) => JSX.Element;
  getPriorityBadge: (priority: string) => JSX.Element;
}

function TicketList({ tickets, onSelectTicket, getStatusBadge, getPriorityBadge }: TicketListProps) {
  if (tickets.length === 0) {
    return (
      <div className="text-center py-12 text-muted-foreground">
        No support tickets found
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {tickets.map((ticket) => (
        <Card key={ticket.id} className="hover:shadow-md transition-shadow cursor-pointer" onClick={() => onSelectTicket(ticket)} data-testid={`ticket-card-${ticket.id}`}>
          <CardContent className="p-6">
            <div className="flex justify-between items-start mb-4">
              <div className="flex-1">
                <h3 className="font-semibold text-lg mb-1" data-testid={`ticket-subject-${ticket.id}`}>{ticket.subject}</h3>
                <p className="text-sm text-muted-foreground">{categoryLabels[ticket.category]}</p>
              </div>
              <div className="flex gap-2">
                {getStatusBadge(ticket.status)}
                {getPriorityBadge(ticket.priority)}
              </div>
            </div>

            <p className="text-sm text-muted-foreground mb-4 line-clamp-2">
              {ticket.message}
            </p>

            <div className="flex items-center gap-6 text-sm text-muted-foreground">
              <div className="flex items-center gap-2">
                <User className="h-4 w-4" />
                <span>{ticket.name}</span>
              </div>
              <div className="flex items-center gap-2">
                <Mail className="h-4 w-4" />
                <span>{ticket.email}</span>
              </div>
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4" />
                <span>{new Date(ticket.createdAt!).toLocaleDateString()}</span>
              </div>
            </div>
          </CardContent>
        </Card>
      ))}
    </div>
  );
}

interface TicketDetailDialogProps {
  ticket: SupportTicket;
  open: boolean;
  onClose: () => void;
  onUpdateStatus: (id: string, status: string) => void;
  onUpdatePriority: (id: string, priority: string) => void;
  getStatusBadge: (status: string) => JSX.Element;
  getPriorityBadge: (priority: string) => JSX.Element;
}

function TicketDetailDialog({ ticket, open, onClose, onUpdateStatus, onUpdatePriority, getStatusBadge, getPriorityBadge }: TicketDetailDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-3" data-testid="dialog-ticket-title">
            <MessageSquare className="h-6 w-6" />
            {ticket.subject}
          </DialogTitle>
          <DialogDescription>
            Ticket ID: {ticket.id}
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 py-4">
          {/* Status & Priority */}
          <div className="flex gap-4">
            <div className="flex-1">
              <Label className="mb-2 block">Status</Label>
              <Select value={ticket.status} onValueChange={(value) => onUpdateStatus(ticket.id, value)}>
                <SelectTrigger data-testid="select-ticket-status">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="open">Open</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="resolved">Resolved</SelectItem>
                  <SelectItem value="closed">Closed</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex-1">
              <Label className="mb-2 block">Priority</Label>
              <Select value={ticket.priority} onValueChange={(value) => onUpdatePriority(ticket.id, value)}>
                <SelectTrigger data-testid="select-ticket-priority">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Customer Info */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Customer Information</CardTitle>
            </CardHeader>
            <CardContent className="space-y-2">
              <div className="flex items-center gap-2">
                <User className="h-4 w-4 text-muted-foreground" />
                <span>{ticket.name} {ticket.userRole && `(${ticket.userRole})`}</span>
              </div>
              <div className="flex items-center gap-2">
                <Mail className="h-4 w-4 text-muted-foreground" />
                <a href={`mailto:${ticket.email}`} className="text-primary hover:underline">
                  {ticket.email}
                </a>
              </div>
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-muted-foreground" />
                <span>Submitted on {new Date(ticket.createdAt!).toLocaleString()}</span>
              </div>
            </CardContent>
          </Card>

          {/* Message */}
          <div>
            <Label className="mb-2 block">Message</Label>
            <div className="bg-muted p-4 rounded-lg">
              <p className="whitespace-pre-wrap" data-testid="ticket-message">{ticket.message}</p>
            </div>
          </div>

          {/* Additional Info */}
          {(ticket.orderId || ticket.processId) && (
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Related Information</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2">
                {ticket.orderId && (
                  <div>
                    <span className="text-sm text-muted-foreground">Order ID: </span>
                    <span className="font-mono">{ticket.orderId}</span>
                  </div>
                )}
                {ticket.processId && (
                  <div>
                    <span className="text-sm text-muted-foreground">Process ID: </span>
                    <span className="font-mono">{ticket.processId}</span>
                  </div>
                )}
              </CardContent>
            </Card>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

