            <Button 
              onClick={handleUpdateDiscount}
              disabled={updateDiscountMutation.isPending}
              data-testid="button-save-discount-edit"
            >
              {updateDiscountMutation.isPending ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

