import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { useCart } from "@/hooks/useCart";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { CheckCircle, Loader2, Package } from "lucide-react";

export default function OrderSuccess() {
  const [, setLocation] = useLocation();
  const [sessionId, setSessionId] = useState<string | null>(null);
  const { clearCart } = useCart();

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const id = params.get('session_id');
    setSessionId(id);

    // Clear the cart after successful payment
    if (id) {
      clearCart();
    }
  }, [clearCart]);

  const { data: order, isLoading } = useQuery<any>({
    queryKey: ["/api/orders/session", sessionId],
    enabled: !!sessionId,
  });

  if (isLoading || !sessionId) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <Card className="max-w-md w-full">
          <CardContent className="pt-6 text-center">
            <Loader2 className="h-12 w-12 animate-spin mx-auto mb-4 text-primary" />
            <p className="text-gray-600">Processing your payment...</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-12">
      <div className="max-w-2xl mx-auto px-4">
        <Card>
          <CardHeader className="text-center">
            <div className="mx-auto mb-4 bg-green-100 rounded-full p-3 w-fit">
              <CheckCircle className="h-12 w-12 text-green-600" />
            </div>
            <CardTitle className="text-2xl">Payment Successful!</CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="text-center">
              <p className="text-gray-600 mb-2">
                Thank you for your order. Your payment has been processed successfully.
              </p>
              {order && (
                <div className="mt-4 p-4 bg-gray-50 rounded-lg">
                  <p className="text-sm text-gray-600 mb-1">Order Number</p>
                  <p className="text-xl font-bold text-gray-900" data-testid="text-order-number">
                    {order.orderNumber}
                  </p>
                  <p className="text-sm text-gray-600 mt-3 mb-1">Total Amount</p>
                  <p className="text-lg font-semibold text-gray-900" data-testid="text-order-total">
                    ${parseFloat(order.totalAmount).toFixed(2)}
                  </p>
                </div>
              )}
            </div>

            <div className="border-t pt-6">
              <h3 className="font-semibold mb-3 flex items-center gap-2">
                <Package className="h-5 w-5" />
                What's Next?
              </h3>
              <ul className="space-y-2 text-sm text-gray-600">
                <li>• You'll receive an order confirmation email shortly</li>
                <li>• Track your order status in your orders page</li>
                <li>• You can view manufacturing progress updates in real-time</li>
                <li>• We'll notify you when your order ships</li>
              </ul>
            </div>

            <div className="flex gap-3">
              <Button
                className="flex-1"
                onClick={() => setLocation("/orders")}
                data-testid="button-view-orders"
              >
                View My Orders
              </Button>
              <Button
                variant="outline"
                className="flex-1"
                onClick={() => setLocation("/products")}
                data-testid="button-continue-shopping"
              >
                Continue Shopping
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/pages/admin/assets.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Edit2, Trash2, Image as ImageIcon } from "lucide-react";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Skeleton } from "@/components/ui/skeleton";
import { SimpleUploader } from "@/components/SimpleUploader";

interface Asset {
  id: string;
  name: string;
  type: string;
  category: string;
  color?: string;
  imageUrl?: string;
  description?: string;
  createdAt: string;
  updatedAt: string;
}

interface AssetFormData {
  name: string;
  type: string;
  color?: string;
  imageUrl?: string;
  description?: string;
}

interface AssetsResponse {
  assets: Asset[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
}

const assetCategories = [
  { value: "wood", label: "Wood" },
  { value: "stain", label: "Stain" },
  { value: "upholstery", label: "Upholstery" },
  { value: "hardware", label: "Hardware" },
  { value: "finish", label: "Finish" },
];

// Default type options for each category
const defaultTypeOptions: Record<string, string[]> = {
  wood: ["Teak", "Oak", "Mahogany", "Walnut", "Pine", "Cherry", "Maple", "Bamboo"],
  stain: ["Natural", "Light Oak", "Dark Walnut", "Ebony", "Cherry", "Mahogany", "Espresso"],
  upholstery: ["Leather", "Fabric", "Velvet", "Linen", "Cotton", "Microfiber", "Suede"],
  hardware: ["Brass", "Chrome", "Stainless Steel", "Bronze", "Nickel", "Copper", "Iron"],
  finish: ["Matte", "Glossy", "Satin", "Oil", "Wax", "Lacquer", "Varnish"],
};

export default function AdminAssets() {
  const [activeTab, setActiveTab] = useState("wood");
  const [editingAsset, setEditingAsset] = useState<Asset | null>(null);
  const [editingAssetGroup, setEditingAssetGroup] = useState<Asset[]>([]);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [isEditGroupDialogOpen, setIsEditGroupDialogOpen] = useState(false);
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [deletingAsset, setDeletingAsset] = useState<Asset | null>(null);
  const [newAsset, setNewAsset] = useState<AssetFormData>({
    name: '',
    type: '',
    color: '',
    description: '',
  });
  const [isAddCustomTypeDialogOpen, setIsAddCustomTypeDialogOpen] = useState(false);
  const [isEditCustomTypeDialogOpen, setIsEditCustomTypeDialogOpen] = useState(false);
  const [customTypeInput, setCustomTypeInput] = useState('');
  const [customTypes, setCustomTypes] = useState<Record<string, string[]>>({
    wood: [],
    stain: [],
    upholstery: [],
    hardware: [],
    finish: [],
  });
  const [isEditMode, setIsEditMode] = useState(false);
  const { toast } = useToast();

  // Fetch assets for the active tab
  const { data: assetsData, isLoading } = useQuery<AssetsResponse>({
    queryKey: ["/api/admin/assets", activeTab],
    queryFn: async () => {
      const response = await apiRequest("GET", `/api/admin/assets?category=${activeTab}`);
      return response.json();
    },
  });

  // Create asset mutation
  const createAssetMutation = useMutation({
    mutationFn: async (data: AssetFormData & { category: string }) => {
      const response = await apiRequest("POST", "/api/admin/assets", data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/assets"] });
      toast({
        title: "Success",
        description: "Asset created successfully",
      });
      setIsCreateDialogOpen(false);
      setNewAsset({ name: '', type: '', color: '', description: '' });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create asset",
        variant: "destructive",
      });
    },
  });

  // Update asset mutation
  const updateAssetMutation = useMutation({
    mutationFn: async ({ assetId, data }: { assetId: string; data: any }) => {
      const response = await apiRequest("PATCH", `/api/admin/assets/${assetId}`, data);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/assets"] });
      toast({
        title: "Success",
        description: "Asset updated successfully",
      });
      setIsEditDialogOpen(false);
      setEditingAsset(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update asset",
        variant: "destructive",
      });
    },
  });

  // Delete asset mutation
  const deleteAssetMutation = useMutation({
    mutationFn: async (assetId: string) => {
      const response = await apiRequest("DELETE", `/api/admin/assets/${assetId}`);
      // 204 No Content responses don't have a body
      if (response.status === 204) {
        return null;
      }
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/admin/assets"] });
      toast({
        title: "Success",
        description: "Asset deleted successfully",
      });
      setIsDeleteDialogOpen(false);
      setDeletingAsset(null);
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete asset",
        variant: "destructive",
      });
    },
  });

  const handleEditAsset = (asset: Asset) => {
    setEditingAsset(asset);
    setIsEditDialogOpen(true);
  };

  const handleEditAssetGroup = (assetGroup: Asset[]) => {
    setEditingAssetGroup(assetGroup);
    setIsEditGroupDialogOpen(true);
  };

  const handleDeleteAsset = (asset: Asset) => {
    setDeletingAsset(asset);
    setIsDeleteDialogOpen(true);
  };

  const confirmDeleteAsset = () => {
    if (deletingAsset) {
      deleteAssetMutation.mutate(deletingAsset.id);
    }
  };

  const handleUpdateAsset = () => {
    if (editingAsset) {
      updateAssetMutation.mutate({
        assetId: editingAsset.id,
        data: {
          name: editingAsset.name,
          type: editingAsset.type,
          color: editingAsset.color,
          imageUrl: editingAsset.imageUrl,
          description: editingAsset.description,
        },
      });
    }
  };

  const handleCreateAsset = () => {
    const assetData = {
      ...newAsset,
      category: activeTab,
    };
    createAssetMutation.mutate(assetData);
  };

  const handleImageUpload = (url: string, isEditing: boolean = false) => {
    if (isEditing && editingAsset) {
      setEditingAsset({ ...editingAsset, imageUrl: url });
    } else {
      setNewAsset({ ...newAsset, imageUrl: url });
    }
  };

  const handleAddCustomType = () => {
    if (!customTypeInput.trim()) {
      toast({
        title: "Error",
        description: "Please enter a type name",
        variant: "destructive",
      });
      return;
    }

    const category = isEditMode && editingAsset ? editingAsset.category : activeTab;

    // Check if type already exists
    const allTypes = [...defaultTypeOptions[category], ...customTypes[category]];
    if (allTypes.includes(customTypeInput.trim())) {
      toast({
        title: "Error",
        description: "This type already exists",
        variant: "destructive",
      });
      return;
    }

    // Add custom type to the list
    setCustomTypes({
      ...customTypes,
      [category]: [...customTypes[category], customTypeInput.trim()],
    });

    // Set the newly added type as selected
    if (isEditMode && editingAsset) {
      setEditingAsset({ ...editingAsset, type: customTypeInput.trim() });
      setIsEditCustomTypeDialogOpen(false);
    } else {
      setNewAsset({ ...newAsset, type: customTypeInput.trim() });
      setIsAddCustomTypeDialogOpen(false);
    }

    setCustomTypeInput('');
    toast({
      title: "Success",
      description: "Custom type added successfully",
    });
  };

  // Get all available types for a category (default + custom)
  const getAvailableTypes = (category: string) => {
    return [...defaultTypeOptions[category], ...(customTypes[category] || [])];
  };

  const renderAssetsTable = (assets: Asset[] | undefined) => {
    if (isLoading) {
      return (
        <div className="space-y-2">
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
          <Skeleton className="h-12 w-full" />
        </div>
      );
    }

    if (!assets || assets.length === 0) {
      return (
        <div className="text-center py-8 text-muted-foreground">
          No assets found. Create your first asset to get started.
        </div>
      );
    }

    // Group assets by name
    const groupedAssets = assets.reduce((acc, asset) => {
      if (!acc[asset.name]) {
        acc[asset.name] = [];
      }
      acc[asset.name].push(asset);
      return acc;
    }, {} as Record<string, Asset[]>);

    const showColorColumn = activeTab === 'stain' || activeTab === 'upholstery';

    // Badge colors for different types
    const badgeColors = [
      'bg-blue-100 text-blue-800 border-blue-300',
      'bg-green-100 text-green-800 border-green-300',
      'bg-purple-100 text-purple-800 border-purple-300',
      'bg-orange-100 text-orange-800 border-orange-300',
      'bg-pink-100 text-pink-800 border-pink-300',
      'bg-cyan-100 text-cyan-800 border-cyan-300',
      'bg-yellow-100 text-yellow-800 border-yellow-300',
      'bg-indigo-100 text-indigo-800 border-indigo-300',
    ];

    return (
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Image</TableHead>
            <TableHead>Name</TableHead>
            <TableHead>Type</TableHead>
            {showColorColumn && <TableHead>Color</TableHead>}
            <TableHead className="text-right">Actions</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {Object.entries(groupedAssets).map(([name, assetGroup]) => (
            <TableRow key={`group-${name}`} data-testid={`asset-row-${name}`}>
              <TableCell>
                {assetGroup[0].imageUrl ? (
                  <img
                    src={assetGroup[0].imageUrl}
                    alt={name}
                    className="h-12 w-12 object-cover rounded"
                    data-testid={`asset-image-${name}`}
                  />
                ) : (
                  <div className="h-12 w-12 bg-muted rounded flex items-center justify-center">
                    <ImageIcon className="h-6 w-6 text-muted-foreground" />
                  </div>
                )}
              </TableCell>
              <TableCell data-testid={`asset-name-${name}`}>{name}</TableCell>
              <TableCell data-testid={`asset-type-${name}`}>
                <div className="flex flex-wrap gap-2">
                  {assetGroup.map((asset, index) => (
                    <span
                      key={asset.id}
                      className={`px-2 py-1 rounded-md text-xs font-medium border ${badgeColors[index % badgeColors.length]}`}
                      data-testid={`type-badge-${asset.id}`}
                    >
                      {asset.type}
                    </span>
                  ))}
                </div>
              </TableCell>
              {showColorColumn && (
                <TableCell data-testid={`asset-color-${name}`}>
                  <div className="flex flex-wrap gap-2">
                    {assetGroup.map((asset) => (
                      asset.color ? (
                        <div key={asset.id} className="flex items-center gap-2">
                          <div 
                            className="w-8 h-8 rounded border border-border" 
                            style={{ backgroundColor: asset.color }}
                          />
                          <span className="text-sm text-muted-foreground">{asset.color}</span>
                        </div>
                      ) : null
                    ))}
                  </div>
                </TableCell>
              )}
              <TableCell className="text-right">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handleEditAssetGroup(assetGroup)}
                  data-testid={`button-edit-group-${name}`}
                >
                  <Edit2 className="h-4 w-4 mr-1" />
                  Edit Group
                </Button>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    );
  };

  return (
    <div className="container mx-auto py-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold" data-testid="page-title">Assets</h1>
          <p className="text-muted-foreground">Manage your furniture assets and materials</p>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Asset Management</CardTitle>
        </CardHeader>
        <CardContent>
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <div className="flex justify-between items-center mb-4">
              <TabsList data-testid="tabs-list">
                {assetCategories.map((category) => (
                  <TabsTrigger
                    key={category.value}
                    value={category.value}
                    data-testid={`tab-${category.value}`}
                  >
                    {category.label}
                  </TabsTrigger>
                ))}
              </TabsList>
              <Button
                onClick={() => setIsCreateDialogOpen(true)}
                data-testid={`button-add-${activeTab}`}
              >
                <Plus className="h-4 w-4 mr-2" />
                Add New Asset
              </Button>
            </div>

            {assetCategories.map((category) => (
              <TabsContent key={category.value} value={category.value} data-testid={`tab-content-${category.value}`}>
                {renderAssetsTable(assetsData?.assets)}
              </TabsContent>
            ))}
          </Tabs>
        </CardContent>
      </Card>

      {/* Create Asset Dialog */}
      <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
        <DialogContent data-testid="dialog-create-asset">
          <DialogHeader>
            <DialogTitle>Add New Asset</DialogTitle>
            <DialogDescription>
              Create a new asset for the {activeTab} category.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="create-type">Type</Label>
              <div className="flex gap-2">
                <Select
                  value={newAsset.type}
                  onValueChange={(value) => {
                    setNewAsset({ ...newAsset, type: value });
                  }}
                >
                  <SelectTrigger data-testid="select-type" className="flex-1">
                    <SelectValue placeholder="Select a type" />
                  </SelectTrigger>
                  <SelectContent>
                    {getAvailableTypes(activeTab).map((type) => (
                      <SelectItem key={type} value={type}>
                        {type}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  variant="outline"
                  size="default"
                  onClick={() => {
                    setIsEditMode(false);
                    setIsAddCustomTypeDialogOpen(true);
                  }}
                  data-testid="button-add-custom"
                >
                  + Add Custom Type
                </Button>
              </div>
            </div>
            <div>
              <Label htmlFor="create-name">Name</Label>
              <Input
                id="create-name"
                type="text"
                value={newAsset.name}
                onChange={(e) => setNewAsset({ ...newAsset, name: e.target.value })}
                placeholder="Enter asset name"
                data-testid="input-name"
              />
            </div>
            {(activeTab === 'stain' || activeTab === 'upholstery') && (
              <div>
                <Label htmlFor="create-color">Color</Label>
                <div className="flex gap-2">
                  <Input
                    id="create-color"
                    type="color"
                    value={newAsset.color || '#000000'}
                    onChange={(e) => setNewAsset({ ...newAsset, color: e.target.value })}
                    className="w-20 h-10 p-1 cursor-pointer"
                    data-testid="input-color"
                  />
                  <Input
                    type="text"
                    value={newAsset.color || ''}
                    onChange={(e) => setNewAsset({ ...newAsset, color: e.target.value })}
                    placeholder="#000000"
                    className="flex-1"
                    data-testid="input-color-hex"
                  />
                </div>
              </div>
            )}
            <div>
              <Label>Image</Label>
              <SimpleUploader
                onUploadSuccess={(url) => handleImageUpload(url, false)}
                allowedTypes={['image/jpeg', 'image/png', 'image/webp', 'image/jpg']}
                maxFileSize={5 * 1024 * 1024}
                className="w-full"
              >
                Upload Image
              </SimpleUploader>
              {newAsset.imageUrl && (
                <div className="mt-2">
                  <img
                    src={newAsset.imageUrl}
                    alt="Preview"
                    className="h-32 w-32 object-cover rounded"
                    data-testid="preview-image"
                  />
                </div>
              )}
            </div>
            <div>
              <Label htmlFor="create-description">Description (Optional)</Label>
              <Textarea
                id="create-description"
                value={newAsset.description || ''}
                onChange={(e) => setNewAsset({ ...newAsset, description: e.target.value })}
                placeholder="Enter asset description"
                rows={3}
                data-testid="input-description"
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setIsCreateDialogOpen(false);
                setNewAsset({ name: '', type: '', color: '', description: '' });
              }}
              data-testid="button-cancel"
            >
              Cancel
            </Button>
            <Button
              onClick={handleCreateAsset}
              disabled={!newAsset.name || !newAsset.type || createAssetMutation.isPending}
              data-testid="button-create"
            >
              {createAssetMutation.isPending ? "Creating..." : "Create Asset"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit Asset Group Dialog */}
      <Dialog open={isEditGroupDialogOpen} onOpenChange={setIsEditGroupDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[80vh] overflow-y-auto" data-testid="dialog-edit-group">
          <DialogHeader>
            <DialogTitle>Edit Asset Group: {editingAssetGroup[0]?.name}</DialogTitle>
            <DialogDescription>
              Manage all types for this asset. Each type can have different properties.
            </DialogDescription>
          </DialogHeader>
          {editingAssetGroup.length > 0 && (
            <div className="space-y-6">
              {/* Common Properties */}
              <div className="space-y-4 p-4 border rounded-lg bg-muted/50">
                <h3 className="font-semibold">Common Properties</h3>
                <div>
                  <Label>Group Name</Label>
                  <p className="text-sm text-muted-foreground mt-1">{editingAssetGroup[0].name}</p>
                </div>
                <div>
                  <Label>Image</Label>
                  {editingAssetGroup[0].imageUrl && (
                    <div className="mt-2">
                      <img
                        src={editingAssetGroup[0].imageUrl}
                        alt="Group preview"
                        className="h-24 w-24 object-cover rounded"
                      />
                    </div>
                  )}
                </div>
              </div>

              {/* Individual Types */}
              <div className="space-y-3">
                <h3 className="font-semibold">Types in this group ({editingAssetGroup.length})</h3>
                {editingAssetGroup.map((asset, index) => {
                  const badgeColors = [
                    'bg-blue-100 text-blue-800 border-blue-300',
                    'bg-green-100 text-green-800 border-green-300',
                    'bg-purple-100 text-purple-800 border-purple-300',
                    'bg-orange-100 text-orange-800 border-orange-300',
                    'bg-pink-100 text-pink-800 border-pink-300',
                    'bg-cyan-100 text-cyan-800 border-cyan-300',
                    'bg-yellow-100 text-yellow-800 border-yellow-300',
                    'bg-indigo-100 text-indigo-800 border-indigo-300',
                  ];

                  return (
                    <div key={asset.id} className="p-4 border rounded-lg space-y-3">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <span className={`px-3 py-1 rounded-md text-sm font-medium border ${badgeColors[index % badgeColors.length]}`}>
                            {asset.type}
                          </span>
                          {(asset.category === 'stain' || asset.category === 'upholstery') && asset.color && (
                            <div className="flex items-center gap-2">
                              <div 
                                className="w-6 h-6 rounded border border-border" 
                                style={{ backgroundColor: asset.color }}
                              />
                              <span className="text-sm text-muted-foreground">{asset.color}</span>
                            </div>
                          )}
                        </div>
                        <div className="flex gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              handleEditAsset(asset);
                              setIsEditGroupDialogOpen(false);
                            }}
                            data-testid={`button-edit-type-${asset.id}`}
                          >
                            <Edit2 className="h-4 w-4 mr-1" />
                            Edit
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              handleDeleteAsset(asset);
                              setIsEditGroupDialogOpen(false);
                            }}
                            data-testid={`button-delete-type-${asset.id}`}
                          >
                            <Trash2 className="h-4 w-4 mr-1" />
                            Delete
                          </Button>
                        </div>
                      </div>
                      {asset.description && (
                        <p className="text-sm text-muted-foreground">{asset.description}</p>
                      )}
                    </div>
                  );
                })}
              </div>

              {/* Add New Type to Group */}
              <div className="p-4 border rounded-lg border-dashed">
                <Button
                  variant="outline"
                  className="w-full"
                  onClick={() => {
                    setNewAsset({
                      name: editingAssetGroup[0].name,
                      type: '',
                      color: '',
                      description: '',
                    });
                    setIsEditGroupDialogOpen(false);
                    setIsCreateDialogOpen(true);
                  }}
                  data-testid="button-add-type-to-group"
                >
                  <Plus className="h-4 w-4 mr-2" />
                  Add New Type to "{editingAssetGroup[0].name}"
                </Button>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setIsEditGroupDialogOpen(false);
                setEditingAssetGroup([]);
              }}
              data-testid="button-close-group"
            >
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit Asset Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent data-testid="dialog-edit-asset">
          <DialogHeader>
            <DialogTitle>Edit Asset</DialogTitle>
            <DialogDescription>
              Update the asset details.
            </DialogDescription>
          </DialogHeader>
          {editingAsset && (
            <div className="space-y-4">
              <div>
                <Label htmlFor="edit-type">Type</Label>
                <div className="flex gap-2">
                  <Select
                    value={editingAsset.type}
                    onValueChange={(value) => {
                      setEditingAsset({ ...editingAsset, type: value });
                    }}
                  >
                    <SelectTrigger data-testid="select-edit-type" className="flex-1">
                      <SelectValue placeholder="Select a type" />
                    </SelectTrigger>
                    <SelectContent>
                      {getAvailableTypes(editingAsset.category).map((type) => (
                        <SelectItem key={type} value={type}>
                          {type}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Button
                    variant="outline"
                    size="default"
                    onClick={() => {
                      setIsEditMode(true);
                      setIsEditCustomTypeDialogOpen(true);
                    }}
                    data-testid="button-edit-add-custom"
                  >
                    + Add Custom Type
                  </Button>
                </div>
              </div>
              <div>
                <Label htmlFor="edit-name">Name</Label>
                <Input
                  id="edit-name"
                  type="text"
                  value={editingAsset.name}
                  onChange={(e) => setEditingAsset({ ...editingAsset, name: e.target.value })}
                  placeholder="Enter asset name"
                  data-testid="input-edit-name"
                />
              </div>
              {(editingAsset.category === 'stain' || editingAsset.category === 'upholstery') && (
                <div>
                  <Label htmlFor="edit-color">Color</Label>
                  <div className="flex gap-2">
                    <Input
                      id="edit-color"
                      type="color"
                      value={editingAsset.color || '#000000'}
                      onChange={(e) => setEditingAsset({ ...editingAsset, color: e.target.value })}
                      className="w-20 h-10 p-1 cursor-pointer"
                      data-testid="input-edit-color"
                    />
                    <Input
                      type="text"
                      value={editingAsset.color || ''}
                      onChange={(e) => setEditingAsset({ ...editingAsset, color: e.target.value })}
                      placeholder="#000000"
                      className="flex-1"
                      data-testid="input-edit-color-hex"
                    />
                  </div>
                </div>
              )}
              <div>
                <Label>Image</Label>
                <SimpleUploader
                  onUploadSuccess={(url) => handleImageUpload(url, true)}
                  allowedTypes={['image/jpeg', 'image/png', 'image/webp', 'image/jpg']}
                  maxFileSize={5 * 1024 * 1024}
                  className="w-full"
                >
                  {editingAsset.imageUrl ? "Change Image" : "Upload Image"}
                </SimpleUploader>
                {editingAsset.imageUrl && (
                  <div className="mt-2">
                    <img
                      src={editingAsset.imageUrl}
                      alt="Preview"
                      className="h-32 w-32 object-cover rounded"
                      data-testid="preview-edit-image"
                    />
                  </div>
                )}
              </div>
              <div>
                <Label htmlFor="edit-description">Description (Optional)</Label>
                <Textarea
                  id="edit-description"
                  value={editingAsset.description || ''}
                  onChange={(e) => setEditingAsset({ ...editingAsset, description: e.target.value })}
                  placeholder="Enter asset description"
                  rows={3}
                  data-testid="input-edit-description"
                />
              </div>
            </div>
          )}
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setIsEditDialogOpen(false);
                setEditingAsset(null);
              }}
              data-testid="button-edit-cancel"
            >
              Cancel
            </Button>
            <Button
              onClick={handleUpdateAsset}
              disabled={!editingAsset?.name || !editingAsset?.type || updateAssetMutation.isPending}
              data-testid="button-save"
            >
              {updateAssetMutation.isPending ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={isDeleteDialogOpen} onOpenChange={setIsDeleteDialogOpen}>
        <AlertDialogContent data-testid="dialog-delete-confirm">
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the asset "{deletingAsset?.name}". This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel data-testid="button-delete-cancel">Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDeleteAsset}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              data-testid="button-delete-confirm"
            >
              {deleteAssetMutation.isPending ? "Deleting..." : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Add Custom Type Dialog (for Create) */}
      <Dialog open={isAddCustomTypeDialogOpen} onOpenChange={setIsAddCustomTypeDialogOpen}>
        <DialogContent data-testid="dialog-add-custom-type">
          <DialogHeader>
            <DialogTitle>Add Custom Type</DialogTitle>
            <DialogDescription>
              Enter a new custom type for {assetCategories.find(c => c.value === activeTab)?.label}. It will be added to the dropdown.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="custom-type-input">Type Name</Label>
              <Input
                id="custom-type-input"
                value={customTypeInput}
                onChange={(e) => setCustomTypeInput(e.target.value)}
                placeholder="Enter type name"
                data-testid="input-custom-type-name"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleAddCustomType();
                  }
                }}
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setIsAddCustomTypeDialogOpen(false);
                setCustomTypeInput('');
              }}
              data-testid="button-custom-type-cancel"
            >
              Cancel
            </Button>
            <Button
              onClick={handleAddCustomType}
              disabled={!customTypeInput.trim()}
              data-testid="button-custom-type-add"
            >
              Add Type
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Add Custom Type Dialog (for Edit) */}
      <Dialog open={isEditCustomTypeDialogOpen} onOpenChange={setIsEditCustomTypeDialogOpen}>
        <DialogContent data-testid="dialog-edit-custom-type">
          <DialogHeader>
            <DialogTitle>Add Custom Type</DialogTitle>
            <DialogDescription>
              Enter a new custom type for {editingAsset && assetCategories.find(c => c.value === editingAsset.category)?.label}. It will be added to the dropdown.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label htmlFor="edit-custom-type-input">Type Name</Label>
              <Input
                id="edit-custom-type-input"
                value={customTypeInput}
                onChange={(e) => setCustomTypeInput(e.target.value)}
                placeholder="Enter type name"
                data-testid="input-edit-custom-type-name"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleAddCustomType();
                  }
                }}
              />
            </div>
          </div>
          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => {
                setIsEditCustomTypeDialogOpen(false);
                setCustomTypeInput('');
              }}
              data-testid="button-edit-custom-type-cancel"
            >
              Cancel
            </Button>
            <Button
              onClick={handleAddCustomType}
              disabled={!customTypeInput.trim()}
              data-testid="button-edit-custom-type-add"
            >
              Add Type
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

